/* ── 3. CheatGUI loader (delayed to ensure game is ready) ──
 * URL is supplied by the extension via window.__ORIGIN_MENU_URL__.
 * The extension resolves: popup override → manifest.defaultMenuUrl.
 * Falls back to the baked-in default if the extension didn't set one
 * (e.g. older extension builds that predate __ORIGIN_MENU_URL__). */
setTimeout(() =>
  (async () => {
    try {
      var url = window.__ORIGIN_MENU_URL__;
      if (typeof url !== "string" || url.length === 0) {
        url = "https://raw.githubusercontent.com/ProdigyPXP/ProdigyOrigin/master/originGUI/dist/bundle.js";
        console.warn("[Play Origin] window.__ORIGIN_MENU_URL__ missing; falling back to default menu URL: " + url);
      }
      eval(await (await fetch(url)).text());
    } catch(e) {
      console.error("[Play Origin] CheatGUI load failed:", e);
    }
  })(), 15000);
